{"source":"#include <stdio.h>
#include <string.h>

char s[100010],p[35];

void constructNext(int* next, int l)
{
    int i;
    next[0]=0;
    for (i=1;i<l;i++)
    {
        int k=next[i-1];
        while (k>0 && p[i]!=p[k])
            k=next[k-1];
        if (p[i]==p[k])
            k++;
        next[i]=k;
    }
}

int main(int argc, char *argv[])
{
    int i,j,ans,sl,pl;
    scanf("%s %s",s,p);
    i=0; j=0; ans=0;
    sl=strlen(s);
    pl=strlen(p);
    int next[pl];
    memset(next,0,sizeof(next));
    constructNext(next,pl);
    while (i<sl)
    {
        if (s[i]==p[j])
        {
            i++;
            j++;
            if (j==pl)
            {
                ans++;
                j=next[j-1];
            }
        }
        else
        {
            if (!j)
                i++;
            else
                j=next[j-1];
        }
    }
    printf("%d\n",ans);
return 0;
}"}
